def _finish_truncated_text(value):
    """Remove source-field clipping artifacts from displayed assessment text."""
    if isinstance(value, list):
        return [_finish_truncated_text(item) for item in value]
    if not isinstance(value, str):
        return value
    if value.endswith(" when empiric tr."):
        return value.split(" when empiric tr.", 1)[0] + "."
    if value.endswith(" (wheez..."):
        return value.split(", bronchoconstriction (wheez...", 1)[0] + "."
    if value.endswith(" by direct laryngoscopy or in..."):
        return value.split(", since airway anatomy can become", 1)[0] + "."
    if value.endswith("...") or value.endswith((" tr.", " ther.")):
        # Some source excerpts were clipped in the middle of a word. Keep only
        # the preceding complete sentence rather than presenting broken prose.
        complete = value.rsplit(". ", 1)[0] if ". " in value else ""
        if complete:
            return complete + "."
        return value.rsplit(" ", 1)[0].rstrip(" ,;:") + "."
    if value.endswith(";"):
        return value[:-1] + "."
    return value


def apply_concept_check_gapfill_v438(data_module, app_module=None):
    checks = data_module.CONCEPT_CHECKS_V112
    existing_ids = {q.get("id") for q in checks}
    added = []
    for entry in NEW_CONCEPT_CHECKS_V438:
        if entry["id"] not in existing_ids:
            row = {key: _finish_truncated_text(value) for key, value in entry.items()}
            if row.get("choices") and isinstance(row.get("answer"), int):
                # The authored bank put every correct MCQ choice in position B.
                # Rotate choices and their explanations together for a stable,
                # varied answer key without changing any clinical content.
                target = hashlib.sha256(row["id"].encode()).digest()[0] % len(row["choices"])
                shift = (target - row["answer"]) % len(row["choices"])
                if shift:
                    for key in ("choices", "why_wrong"):
                        row[key] = row[key][-shift:] + row[key][:-shift]
                    row["answer"] = target
            checks.append(row)
            existing_ids.add(entry["id"])
            added.append(entry["id"])
    data_module.CONCEPT_CHECK_BY_ID_V112 = {q["id"]: q for q in checks if q.get("id")}
    if app_module is not None:
        app_module.CONCEPT_CHECKS_V112 = checks
        app_module.CONCEPT_CHECK_BY_ID_V112 = data_module.CONCEPT_CHECK_BY_ID_V112
    return {"added_count": len(added)}
